import { useState, useEffect } from 'react'
import {
  getSysParameterList,
  editSysParameter,
  getSysParameterLogList,
  SystemConfigTypes
} from '@/apis/admin/system-config'
import ExcelTable from '@/components/exportExcel'
import {
  PageContainer,
  ProCard,
  ProForm,
  ProFormInstance,
  ProFormDigit,
  ProFormSwitch
} from '@ant-design/pro-components'
import {
  Button,
  message,
  Space,
  Card,
  Row,
  Col,
  Form,
  InputNumber,
  Switch,
  Table,
  Tooltip,
  Alert
} from 'antd'
import {
  SaveOutlined,
  ReloadOutlined,
  ToolOutlined,
  InfoCircleOutlined,
  ClockCircleOutlined,
  QrcodeOutlined,
  HourglassOutlined,
  WarningOutlined,
  HeartOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import type { ColumnsType } from 'antd/es/table'

interface ParamConfig {
  id: number
  configKey: string
  configValue: string
  configName: string
  configType: number
  sort: number
  status: number
}

const Params: React.FC = () => {
  const [formRef] = Form.useForm()
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [paramList, setParamList] = useState<ParamConfig[]>([])
  const [logList, setLogList] = useState<SystemConfigTypes.SysParameterConfigLogsListDto[]>([])
  const [logLoading, setLogLoading] = useState(false)
  const [logPagination, setLogPagination] = useState({
    current: 1,
    pageSize: 10,
    total: 0
  })

  // 参数配置映射
  const [params, setParams] = useState({
    lockTimeout: 5, // 格口锁定超时时间（分钟）
    codeLength: 6, // 取件码位数
    codeValidity: 72, // 取件码有效期（小时）
    overdueThreshold: 3, // 滞留件全局超期阈值（天）
    heartbeatTimeout: 120, // 设备心跳超时阈值（秒）
  })

  // 加载参数列表
  const loadParamList = async () => {
    setLoading(true)
    try {
      const res = await getSysParameterList()
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        setParamList(res.data.list)
        // 解析参数值到表单
        const newParams = { ...params }
        res.data.list.forEach((item: ParamConfig) => {
          switch (item.configKey) {
            case 'lock_timeout':
              newParams.lockTimeout = parseInt(item.configValue) || 5
              break
            case 'code_length':
              newParams.codeLength = parseInt(item.configValue) || 6
              break
            case 'code_validity':
              newParams.codeValidity = parseInt(item.configValue) || 72
              break
            case 'overdue_threshold':
              newParams.overdueThreshold = parseInt(item.configValue) || 3
              break
            case 'heartbeat_timeout':
              newParams.heartbeatTimeout = parseInt(item.configValue) || 120
              break
            default:
              break
          }
        })
        setParams(newParams)
        formRef.setFieldsValue(newParams)
      }
    } catch (e) {
      console.error('加载参数列表失败:', e)
      message.error('加载参数失败')
    } finally {
      setLoading(false)
    }
  }

  // 加载日志列表
  const loadLogList = async (page = 1, pageSize = 10) => {
    setLogLoading(true)
    try {
      const res = await getSysParameterLogList({ page, pageSize })
      if (res.code === ResultEnum.SUCCESS && res.data) {
        setLogList(res.data.list || [])
        setLogPagination({
          current: res.data.page,
          pageSize: res.data.pageSize,
          total: res.data.totalCount
        })
      }
    } catch (e) {
      console.error('加载日志列表失败:', e)
    } finally {
      setLogLoading(false)
    }
  }

  useEffect(() => {
    loadParamList()
    loadLogList()
  }, [])

  // 保存参数
  const handleSave = async () => {
    try {
      const values = await formRef.validateFields()
      setSaving(true)

      // 构建参数数组
      const parameters: SystemConfigTypes.SysParameterItem[] = [
        { id: getParamId('lock_timeout'), configValue: String(values.lockTimeout), configName: '格口锁定超时时间' },
        { id: getParamId('code_length'), configValue: String(values.codeLength), configName: '取件码位数' },
        { id: getParamId('code_validity'), configValue: String(values.codeValidity), configName: '取件码有效期' },
        { id: getParamId('overdue_threshold'), configValue: String(values.overdueThreshold), configName: '滞留件全局超期阈值' },
        { id: getParamId('heartbeat_timeout'), configValue: String(values.heartbeatTimeout), configName: '设备心跳超时阈值' },
      ]

      const res = await editSysParameter({ parameters })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('参数已保存')
        loadLogList() // 刷新日志
      } else {
        message.error('保存失败')
      }
    } catch (e) {
      console.error(e)
    } finally {
      setSaving(false)
    }
  }

  // 获取参数ID
  const getParamId = (key: string): number => {
    const param = paramList.find(p => p.configKey === key)
    return param?.id || 0
  }

  // 恢复默认
  const handleReset = () => {
    const defaultParams = {
      lockTimeout: 5,
      codeLength: 6,
      codeValidity: 72,
      overdueThreshold: 3,
      heartbeatTimeout: 120,
    }
    formRef.setFieldsValue(defaultParams)
    message.success('已恢复默认配置')
  }

  // 日志表格列
  const logColumns: ColumnsType<SystemConfigTypes.SysParameterConfigLogsListDto> = [
    {
      title: '修改时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 180,
      render: (text) => <span style={{ color: '#64748B', fontSize: 12 }}>{text}</span>
    },
    {
      title: '参数名',
      dataIndex: 'paramName',
      key: 'paramName',
      width: 160,
    },
    {
      title: '修改前',
      dataIndex: 'beforeValue',
      key: 'beforeValue',
      width: 140,
      render: (text) => <span style={{ fontFamily: 'monospace' }}>{text}</span>
    },
    {
      title: '修改后',
      dataIndex: 'afterValue',
      key: 'afterValue',
      width: 140,
      render: (text) => <span style={{ fontFamily: 'monospace', fontWeight: 600 }}>{text}</span>
    },
    {
      title: '操作人',
      dataIndex: 'operateUserName',
      key: 'operateUserName',
      width: 120,
    },
  ]

  // 参数项渲染组件
  const ParamItem = ({
    icon,
    label,
    value,
    unit,
    description,
    min,
    max,
    name,
    isSwitch = false
  }: {
    icon: React.ReactNode
    label: string
    value?: number | boolean
    unit?: string
    description: string
    min?: number
    max?: number
    name: string
    isSwitch?: boolean
  }) => (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      padding: '16px 0',
      borderBottom: '1px solid #F1F5F9'
    }}>
      <div style={{ width: 220, fontSize: 14, fontWeight: 500, color: '#1f2937', flexShrink: 0 }}>
        <Space>
          {icon}
          {label}
        </Space>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>
        <Form.Item name={name} noStyle valuePropName={isSwitch ? 'checked' : 'value'}>
          {isSwitch ? (
            <Switch checkedChildren="开启" unCheckedChildren="关闭" />
          ) : (
            <InputNumber
              min={min}
              max={max}
              style={{ width: 100, textAlign: 'center' }}
            />
          )}
        </Form.Item>
        {!isSwitch && unit && <span style={{ fontSize: 13, color: '#6b7280' }}>{unit}</span>}
      </div>
      <div style={{ flex: 1, marginLeft: 24, fontSize: 12, color: '#9ca3af' }}>
        {description}
      </div>
    </div>
  )

  return (
    <PageContainer
      header={{
        title: (
          <Space>
            <ToolOutlined style={{ color: '#1890ff' }} />
            <span style={{ fontSize: 20, fontWeight: 600 }}>系统参数</span>
          </Space>
        ),
        breadcrumb: undefined,
      }}
    >
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        {/* 参数配置卡片 */}
        <ProCard
          title={
            <Space>
              <ToolOutlined style={{ color: '#1890ff' }} />
              参数配置
            </Space>
          }
          bordered
          headerBordered
          extra={
            <Space>
              <Button
                icon={<ReloadOutlined />}
                onClick={handleReset}
              >
                恢复默认
              </Button>
              <Button
                type="primary"
                icon={<SaveOutlined />}
                onClick={handleSave}
                loading={saving}
              >
                保存配置
              </Button>
            </Space>
          }
        >
          <Form
            form={formRef}
            layout="vertical"
            initialValues={params}
          >
            <ParamItem
              icon={<ClockCircleOutlined style={{ color: '#1890ff' }} />}
              label="格口锁定超时时间"
              unit="分钟"
              description="用户下单后未存入物品，格口自动释放的等待时间"
              min={1}
              max={30}
              name="lockTimeout"
            />
            <ParamItem
              icon={<QrcodeOutlined style={{ color: '#1890ff' }} />}
              label="取件码位数"
              unit="位"
              description="系统生成取件码的位数，建议6位，兼顾安全性和易用性"
              min={4}
              max={8}
              name="codeLength"
            />
            <ParamItem
              icon={<HourglassOutlined style={{ color: '#1890ff' }} />}
              label="取件码有效期"
              unit="小时"
              description="取件码生成后的有效时长，超过有效期需重新获取"
              min={1}
              max={720}
              name="codeValidity"
            />
            <ParamItem
              icon={<WarningOutlined style={{ color: '#faad14' }} />}
              label="滞留件全局超期阈值"
              unit="天"
              description="物品存放超过此时间后标记为滞留件，触发超期提醒"
              min={1}
              max={30}
              name="overdueThreshold"
            />
            <ParamItem
              icon={<HeartOutlined style={{ color: '#52c41a' }} />}
              label="设备心跳超时阈值"
              unit="秒"
              description="设备超过此时间未上报心跳则判定为离线，触发告警"
              min={30}
              max={600}
              name="heartbeatTimeout"
            />
          </Form>
        </ProCard>

        {/* 修改记录 */}
        <ProCard
          title={
            <Space>
              <InfoCircleOutlined style={{ color: '#1890ff' }} />
              修改记录
            </Space>
          }
          bordered
          headerBordered
        >
          <Table
            columns={logColumns}
            dataSource={logList}
            rowKey="id"
            loading={logLoading}
            pagination={{
              ...logPagination,
              onChange: (page, pageSize) => {
                loadLogList(page, pageSize)
              }
            }}
            size="small"
          />
        </ProCard>
      </Space>
    </PageContainer>
  )
}

export default Params